<?php require __DIR__.'/../includes/bootstrap.php';require_role(['agent','admin']);$title='Planning agence';$q=$pdo->query("SELECT 'Hébergement' kind,b.id,u.nom client,b.prix_total,b.statut,b.created_at FROM room_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'Billet',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM ticket_bookings b JOIN users u ON u.id=b.user_id UNION ALL SELECT 'Circuit',b.id,u.nom,b.prix_total,b.statut,b.created_at FROM package_bookings b JOIN users u ON u.id=b.user_id ORDER BY created_at DESC LIMIT 100");$rows=$q->fetchAll();$today=(int)$pdo->query('SELECT COUNT(*) FROM room_bookings WHERE DATE(created_at)=CURDATE()')->fetchColumn();require __DIR__.'/../includes/header.php';?>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="page-heading"><p class="page-eyebrow">Espace agent · Guichet</p><h1 class="page-title">Planning des réservations</h1><p class="page-subtitle">Retrouvez les ventes récentes et accompagnez vos voyageurs.</p></div><div class="grid sm:grid-cols-3 gap-4 mt-5"><article class="dashboard-stat"><span>Réservations récentes affichées</span><strong><?=count($rows)?></strong></article><article class="dashboard-stat"><span>Réservations hôtel aujourd'hui</span><strong><?=$today?></strong></article><article class="dashboard-stat"><span>Vue agence</span><strong class="!text-xl">À jour</strong></article></div><div class="flex justify-between items-end mt-10"><div><p class="page-eyebrow">Activité de l'agence</p><h2 class="text-2xl font-black mt-1">Dernières réservations</h2></div></div><div class="table-wrap mt-4"><table><thead><tr><th>Produit</th><th>Client</th><th>Référence</th><th>Montant</th><th>Statut</th><th>Créée le</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><span class="pill"><?=e($r['kind'])?></span></td><td><?=e($r['client'])?></td><td>#<?=$r['id']?></td><td><?=money($r['prix_total'])?></td><td><?=e(str_replace('_',' ',$r['statut']))?></td><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Aucune réservation enregistrée.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
